class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        # Helper function to check if it's possible to mark all indices within first `s` seconds
        def check(s):
            # Map index -> index of its last occurrence in changeIndices[0...s-1]
            last_occurrence = {}
            for i in range(s):
                last_occurrence[changeIndices[i]] = i

            # If not all indices can be marked (i.e., some index never appears), return False
            if len(last_occurrence) < n:
                return False

            # Events: key is the time 't' (0 to m-1), value is the index that needs to be marked
            events = [[] for _ in range(s)]
            for idx, time in last_occurrence.items():
                events[time].append(idx)

            # Available "decrement" operations count
            decrements_needed = 0

            # Traverse backwards from time s-1 down to 0
            # If we encounter a time that is a marked time for an index, we must have finished
            # decrementing it before this time.
            for t in range(s - 1, -1, -1):
                if events[t]:
                    # We are at a time where some index must be marked.
                    # We need to process all indices that have their last occurrence at this time.
                    for idx in events[t]:
                        # The count of decrements for this index is nums[idx-1]
                        decrements_needed += nums[idx - 1] + 1
                else:
                    # If we have decrements pending, we can use this free second to perform one
                    if decrements_needed > 0:
                        decrements_needed -= 1

            # If we still have decrements needed, it means we didn't have enough time
            return decrements_needed == 0

        # Binary search for the earliest second
        low = 1
        high = m
        ans = -1

        while low <= high:
            mid = (low + high) // 2
            if check(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1

        return ans
